188	interface ParsedOptions {
189	  devices: string[];
190	  from?: number;
191	  to?: number;
192	  tz?: string;
193	}
194	
195	/** 解析 --device/--from/--to(及允许时的 --tz)选项;出错返回错误消息字符串。 */
196	function parseOptions(rest: string[], allowTz = false): ParsedOptions | string {
197	  const devices: string[] = [];
198	  let from: number | undefined;
199	  let to: number | undefined;
200	  let tz: string | undefined;
201	  for (let i = 0; i < rest.length; i++) {
202	    let opt = rest[i];
203	    let value: string | undefined;
204	    const eq = opt.indexOf('=');
205	    if (opt.startsWith('--') && eq !== -1) {
206	      value = opt.slice(eq + 1);
207	      opt = opt.slice(0, eq);
208	    } else if (opt.startsWith('--')) {
209	      value = rest[i + 1];
210	      if (value === undefined) return `选项 '${opt}' 缺少值`;
211	      i++;
212	    } else {
213	      return `无法识别的参数 '${opt}'`;
214	    }
215	    if (opt === '--device') {
216	      if (value.trim() === '') return "'--device' 的值不能为空";
217	      devices.push(value);
218	    } else if (opt === '--from' || opt === '--to') {
219	      const ts = parseIso8601(value.trim());
220	      if (ts === null) {
221	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
222	      }
223	      if (opt === '--from') from = ts;
224	      else to = ts;
225	    } else if (opt === '--tz' && allowTz) {
226	      tz = value.trim();
227	      if (tz === '') return "'--tz' 的值不能为空";
228	    } else {
229	      return `无法识别的选项 '${opt}'`;
230	    }
231	  }
232	  return { devices, from, to, tz };
233	}
234	
235	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
236	function checkTz(tz: string): string | null {
237	  if (loadTimezone(tz) === null) {
238	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
239	  }
240	  return null;
241	}
242	
243	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
244	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
245	  const out = new Map<string, string[]>();
246	  for (let i = 0; i < rest.length; i++) {
247	    let opt = rest[i];
248	    let value: string | undefined;
249	    const eq = opt.indexOf('=');
250	    if (opt.startsWith('--') && eq !== -1) {
251	      value = opt.slice(eq + 1);
252	      opt = opt.slice(0, eq);
253	    } else if (opt.startsWith('--')) {
254	      value = rest[i + 1];
255	      if (value === undefined) return `选项 '${opt}' 缺少值`;
256	      i++;
257	    } else {
258	      return `无法识别的参数 '${opt}'`;
259	    }
260	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
261	    const list = out.get(opt);
262	    if (list) list.push(value);
263	    else out.set(opt, [value]);
264	  }
265	  return out;
266	}
267	
268	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
269	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
270	  const list = flags.get(name);
271	  if (!list || list.length !== 1) return null;
272	  return list[0];
273	}
274	
275	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
276	function dateFlag(value: string, label: string): { date: string } | string {
277	  const v = value.trim();
278	  if (parseUtcDate(v) === null) {
279	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
280	  }
281	  return { date: v };
282	}
