284	function cmdRule(rest: string[]): number {
285	  const [sub, ...subrest] = rest;
286	  if (sub === 'list') {
287	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
288	    return cmdRuleList();
289	  }
290	  if (sub === 'create') {
291	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz']);
292	    if (typeof flags === 'string') return usageError(flags);
293	    const idRaw = oneFlag(flags, '--id');
294	    const deviceList = flags.get('--device');
295	    const groupList = flags.get('--group');
296	    const thresholdRaw = oneFlag(flags, '--threshold');
297	    const tzList = flags.get('--tz');
298	    if (idRaw === null || thresholdRaw === null) {
299	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
300	    }
301	    if (tzList !== undefined && tzList.length !== 1) {
302	      return usageError("'rule create' 的 --tz 只能出现一次");
303	    }
304	    const hasDevice = deviceList !== undefined;
305	    const hasGroup = groupList !== undefined;
306	    if (hasDevice === hasGroup) {
307	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
308	    }
309	    if ((deviceList !== undefined && deviceList.length !== 1) ||
310	      (groupList !== undefined && groupList.length !== 1)) {
311	      return usageError("'rule create' 的目标选项只能出现一次");
312	    }
313	    const id = idRaw.trim();
314	    if (id === '') return usageError('规则标识不能为空');
315	    const thresholdMilli = parseKwh(thresholdRaw.trim());
316	    if (thresholdMilli === null) {
317	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
318	    }
319	    // 时区省略与显式 UTC 等价;按运行环境解析后的规范名存储与比较。
320	    let tz = 'UTC';
321	    if (tzList !== undefined) {
322	      const tzRaw = tzList[0].trim();
323	      if (tzRaw === '') return usageError("'--tz' 的值不能为空");
324	      const canonical = canonicalTimezone(tzRaw);
325	      if (canonical === null) {
326	        return usageError(`未知时区 '${tzRaw}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`);
327	      }
328	      tz = canonical;
329	    }
330	    if (hasDevice) {
331	      const device = (deviceList as string[])[0].trim();
332	      if (device === '') return usageError("'--device' 的值不能为空");
333	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli, tz });
334	    }
335	    const group = (groupList as string[])[0].trim();
336	    if (group === '') return usageError("'--group' 的值不能为空");
337	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli, tz });
338	  }
339	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
340	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
341	}
342	
343	function cmdEvaluateEntry(rest: string[]): number {
344	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
345	  if (typeof flags === 'string') return usageError(flags);
346	  const ruleRaw = oneFlag(flags, '--rule');
347	  const fromRaw = oneFlag(flags, '--from');
348	  const toRaw = oneFlag(flags, '--to');
349	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
350	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
351	  }
352	  const ruleId = ruleRaw.trim();
353	  if (ruleId === '') return usageError('规则标识不能为空');
354	  const from = dateFlag(fromRaw, '起始日期');
355	  if (typeof from === 'string') return usageError(from);
356	  const to = dateFlag(toRaw, '结束日期');
357	  if (typeof to === 'string') return usageError(to);
358	  if (from.date >= to.date) return usageError('评估起日必须早于止日(--from < --to)');
359	  return cmdEvaluate({ ruleId, from: from.date, to: to.date });
360	}
361	
362	function cmdAlertsEntry(rest: string[]): number {
363	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
364	  if (typeof flags === 'string') return usageError(flags);
365	  const ruleRaw = oneFlag(flags, '--rule');
366	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
367	  const ruleId = ruleRaw.trim();
