375	  let to: string | undefined;
376	  if (fromList !== undefined) {
377	    const fromRaw = oneFlag(flags, '--from');
378	    const toRaw = oneFlag(flags, '--to');
379	    if (fromRaw === null || toRaw === null) {
380	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
381	    }
382	    const fromParsed = dateFlag(fromRaw, '起始日期');
383	    if (typeof fromParsed === 'string') return usageError(fromParsed);
384	    const toParsed = dateFlag(toRaw, '结束日期');
385	    if (typeof toParsed === 'string') return usageError(toParsed);
386	    if (fromParsed.date >= toParsed.date) return usageError('查询起日必须早于止日(--from < --to)');
387	    from = fromParsed.date;
388	    to = toParsed.date;
389	  }
390	  return cmdAlerts({ ruleId, from, to });
391	}
