393	function cmdGroup(rest: string[]): number {
394	  const [sub, ...subrest] = rest;
395	  if (sub === 'configure') {
396	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
397	    if (typeof flags === 'string') return usageError(flags);
398	    const idRaw = oneFlag(flags, '--id');
399	    const atRaw = oneFlag(flags, '--at');
400	    const deviceList = flags.get('--device') ?? [];
401	    if (idRaw === null || atRaw === null) {
402	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
403	    }
404	    if (deviceList.length === 0) {
405	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
406	    }
407	    const id = idRaw.trim();
408	    if (id === '') return usageError('分组标识不能为空');
409	    const at = parseIso8601(atRaw.trim());
410	    if (at === null) {
411	      return usageError(
412	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
413	      );
414	    }
415	    const members: string[] = [];
416	    for (const d of deviceList) {
417	      const m = d.trim();
