437	    const toRaw = oneFlag(flags, '--to');
438	    if (idRaw === null || fromRaw === null || toRaw === null) {
439	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
440	    }
441	    const tzList = flags.get('--tz');
442	    if (tzList !== undefined && tzList.length !== 1) {
443	      return usageError("'group daily' 的 --tz 只能出现一次");
444	    }
445	    const id = idRaw.trim();
446	    if (id === '') return usageError('分组标识不能为空');
447	    const from = parseIso8601(fromRaw.trim());
