468	
469	/**
470	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
471	 * 各恰好一个。出错返回错误消息字符串。
472	 */
473	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
474	  const segments: string[][] = [[]];
475	  for (const tok of rest) {
476	    if (tok === '--item') segments.push([]);
477	    else segments[segments.length - 1].push(tok);
478	  }
479	  const headFlags = parseFlags(segments[0], ['--request']);
480	  if (typeof headFlags === 'string') return headFlags;
481	  const requestRaw = oneFlag(headFlags, '--request');
482	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
483	  const requestId = requestRaw.trim();
484	  if (requestId === '') return '请求标识不能为空';
485	  const itemSegs = segments.slice(1);
486	  if (itemSegs.length === 0) {
487	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
488	  }
489	  const items: CorrectionItem[] = [];
490	  for (const seg of itemSegs) {
491	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
492	    if (typeof flags === 'string') return flags;
493	    const deviceRaw = oneFlag(flags, '--device');
494	    const atRaw = oneFlag(flags, '--at');
495	    const expectRaw = oneFlag(flags, '--expect');
496	    const setRaw = oneFlag(flags, '--set');
497	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
498	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
499	    }
500	    const device = deviceRaw.trim();
501	    if (device === '') return "'--device' 的值不能为空";
502	    const ts = parseIso8601(atRaw.trim());
503	    if (ts === null) {
504	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
505	    }
506	    const expectedMilli = parseKwh(expectRaw.trim());
507	    if (expectedMilli === null) {
508	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
509	    }
510	    const replacementMilli = parseKwh(setRaw.trim());
511	    if (replacementMilli === null) {
512	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
513	    }
514	    items.push({ device, ts, expectedMilli, replacementMilli });
515	  }
516	  return { requestId, items };
517	}
518	
519	function cmdCorrectEntry(rest: string[]): number {
520	  const parsed = parseCorrectItems(rest);
521	  if (typeof parsed === 'string') return usageError(parsed);
522	  return cmdCorrect(parsed.requestId, parsed.items);
523	}
524	
