526	  const flags = parseFlags(rest, ['--request', '--target']);
527	  if (typeof flags === 'string') return usageError(flags);
528	  const requestRaw = oneFlag(flags, '--request');
529	  const targetRaw = oneFlag(flags, '--target');
530	  if (requestRaw === null || targetRaw === null) {
531	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
532	  }
533	  const requestId = requestRaw.trim();
534	  if (requestId === '') return usageError('撤销请求标识不能为空');
535	  const targetId = targetRaw.trim();
536	  if (targetId === '') return usageError('目标修正请求标识不能为空');
537	  return cmdUndo(requestId, targetId);
538	}
