549	  }
550	
551	  if (cmd === 'import') {
552	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
553	    return cmdImport(rest[0]);
554	  }
555	
556	  if (cmd === 'readings') {
557	    const parsed = parseOptions(rest);
558	    if (typeof parsed === 'string') return usageError(parsed);
559	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
560	      return usageError('查询起点必须早于终点(--from < --to)');
561	    }
562	    return cmdReadings(parsed);
