568	    if (parsed.from === undefined || parsed.to === undefined) {
569	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
570	    }
571	    if (parsed.from >= parsed.to) {
572	      return usageError('查询起点必须早于终点(--from < --to)');
573	    }
574	    if (parsed.tz !== undefined) {
575	      const bad = checkTz(parsed.tz);
576	      if (bad !== null) return usageError(bad);
577	    }
578	    return cmdDaily({ devices: parsed.devices, from: parsed.from, to: parsed.to, tz: parsed.tz });
579	  }
580	
581	  if (cmd === 'rule') return cmdRule(rest);
582	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
583	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
584	  if (cmd === 'group') return cmdGroup(rest);
