export function groupFilePath(): string {
  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
  return join(dir, 'groups.json');
}

/**
 * 解析存储中的毫千瓦时字段:十进制数字字符串,或旧格式的安全整数数值。
