314	/** 一天各实际 UTC 时段的展示行(时段按实际时刻升序)。 */
315	function periodLines(day: LocalDay): string[] {
316	  return day.periods.map((p) => `    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
317	}
318	
319	/** 规则时区的墙钟格式化器;存储载入时已校验,此处不会失败。 */
320	function ruleFormat(rule: AlertRule): Intl.DateTimeFormat {
321	  const fmt = loadTimezone(rule.tz);
322	  if (fmt === null) {
323	    throw new StoreError(`rule '${rule.id}' has invalid timezone '${rule.tz}' in storage`);
324	  }
325	  return fmt;
326	}
327	
328	/**
329	 * 计算规则在一个当地日期上的统计:汇总归属该日期的全部实际 UTC 时段。
330	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径;
331	 * 日界线与成员切换都不重置各设备原读数区间的分摊起点。
332	 */
333	function computeRuleDay(env: RuleEnv, day: LocalDay): DayStats {
334	  let valid = 0;
335	  let anomaly = 0;
336	  let unknown = 0;
337	  let consumption = 0n;
338	  for (const p of day.periods) {
339	    if (env.kind === 'device') {
340	      const s = computeDay(env.series, p.start, p.end);
341	      valid += s.valid;
342	      anomaly += s.anomaly;
343	      unknown += s.unknown;
344	      consumption += s.consumption;
345	    } else {
346	      const s = computeGroupSegment(env.group.versions, env.byDevice, p.start, p.end);
347	      valid += s.valid;
348	      anomaly += s.anomaly;
349	      unknown += s.unknown;
350	      consumption += s.consumption;
351	    }
352	  }
353	  return { valid, anomaly, unknown, consumption };
354	}
355	
356	/**
357	 * 创建规则。相同标识、同目标类型、同目标标识、等价阈值及同时区(规范名)
358	 * 重试成功且不重复创建;任一不同即报冲突。设备必须已有存储读数;分组必须
359	 * 已配置。返回进程退出码。
360	 */
361	export function cmdRuleCreate(opts: {
362	  id: string;
363	  targetType: RuleTargetType;
364	  targetId: string;
365	  thresholdMilli: bigint;
366	  /** 规范 IANA 时区名(调用方已解析;省略时传 'UTC')。 */
367	  tz: string;
368	}): number {
369	  const statePath = alertFilePath();
370	  let state: AlertState;
371	  try {
372	    state = loadAlertState(statePath);
373	  } catch (e) {
374	    if (e instanceof StoreError) {
375	      err(e.message);
376	      return 1;
377	    }
378	    throw e;
379	  }
380	
381	  const got = `${opts.targetType}=${opts.targetId}`;
382	  const existing = state.rules.find((r) => r.id === opts.id);
383	  if (existing) {
384	    if (
385	      existing.targetType === opts.targetType &&
386	      existing.targetId === opts.targetId &&
387	      existing.thresholdMilli === opts.thresholdMilli &&
388	      existing.tz === opts.tz
389	    ) {
390	      console.log(
391	        `rule '${opts.id}' already exists with identical parameters (${targetLabel(existing)} ` +
392	          `threshold=${formatKwh(existing.thresholdMilli)} kWh tz=${existing.tz}); unchanged`,
393	      );
394	      return 0;
395	    }
396	    err(
397	      `rule '${opts.id}' already exists with different parameters ` +
398	        `(stored ${targetLabel(existing)} threshold=${formatKwh(existing.thresholdMilli)} kWh ` +
399	        `tz=${existing.tz}, got ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh ` +
400	        `tz=${opts.tz}); conflict`,
401	    );
402	    return 1;
403	  }
404	
405	  // 目标存在性:设备需已有存储读数;分组需已配置(配置时已保证成员设备存在)。
406	  try {
407	    if (opts.targetType === 'device') {
408	      const devices = new Set(loadStore(dataFilePath()).map((r) => r.device));
409	      if (!devices.has(opts.targetId)) {
410	        err(`unknown device '${opts.targetId}': no stored readings; import readings before creating a rule`);
411	        return 1;
412	      }
413	    } else {
414	      const groups = loadGroups(groupFilePath());
415	      if (!groups.some((g) => g.id === opts.targetId)) {
416	        err(`unknown group '${opts.targetId}': configure the group before creating a rule`);
417	        return 1;
418	      }
419	    }
420	  } catch (e) {
421	    if (e instanceof StoreError) {
422	      err(e.message);
423	      return 1;
424	    }
425	    throw e;
426	  }
427	
428	  state.rules.push({
429	    id: opts.id,
430	    targetType: opts.targetType,
431	    targetId: opts.targetId,
432	    thresholdMilli: opts.thresholdMilli,
433	    tz: opts.tz,
434	  });
435	  try {
436	    saveAlertState(statePath, state);
437	  } catch (e) {
438	    if (e instanceof StoreError) {
439	      err(e.message);
440	      return 1;
441	    }
442	    throw e;
443	  }
444	  console.log(
445	    `rule '${opts.id}' created: ${got} threshold=${formatKwh(opts.thresholdMilli)} kWh tz=${opts.tz}`,
446	  );
447	  return 0;
448	}
449	
450	/** 列出全部规则(含目标类型与时区)。只读。返回进程退出码。 */
451	export function cmdRuleList(): number {
452	  let state: AlertState;
453	  try {
454	    state = loadAlertState(alertFilePath());
455	  } catch (e) {
456	    if (e instanceof StoreError) {
457	      err(e.message);
458	      return 1;
459	    }
460	    throw e;
461	  }
462	  if (state.rules.length === 0) {
463	    console.log('no rules defined');
464	    return 0;
465	  }
466	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
467	  for (const r of rules) {
468	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
469	    console.log(
470	      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  ` +
471	        `tz=${r.tz}  open alerts=${open}`,
472	    );
473	  }
474	  return 0;
475	}
476	
477	/**
478	 * 评估规则在连续完整当地日期范围 [from, to)(规则时区的 YYYY-MM-DD,起日含、
479	 * 止日不含)上的超限情况。每个日期统计归属该日期的全部实际 UTC 时段,一次
480	 * 评估只作一次判定;整日被跳过的日期标明跳过,不判定、不创建也不恢复告警。
481	 * 全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途任一存储
482	 * 或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
483	 */
484	export function cmdEvaluate(opts: { ruleId: string; from: string; to: string }): number {
485	  const statePath = alertFilePath();
486	  let state: AlertState;
487	  let rule: AlertRule;
488	  let env: RuleEnv;
489	  let fmt: Intl.DateTimeFormat;
490	  try {
491	    state = loadAlertState(statePath);
492	    const found = state.rules.find((r) => r.id === opts.ruleId);
493	    if (!found) {
494	      err(`unknown rule '${opts.ruleId}'`);
495	      return 1;
496	    }
497	    rule = found;
498	    env = prepareEnv(rule);
499	    fmt = ruleFormat(rule);
500	  } catch (e) {
501	    if (e instanceof StoreError) {
502	      err(e.message);
503	      return 1;
504	    }
505	    throw e;
506	  }
507	
508	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
509	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
510	  const alertIds = new Set(state.alerts.map((a) => a.id));
511	
512	  const threshold = rule.thresholdMilli;
513	  const lines: string[] = [];
514	  for (const { label, day } of localDateRange(fmt, opts.from, opts.to)) {
515	    if (day === null) {
516	      // 整日被跳过(无实际时段):不判定、不触发也不恢复。
517	      lines.push(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})  no alert action`);
518	      continue;
519	    }
520	    const stats = computeRuleDay(env, day);
521	    const coverage = coverageSuffix(stats);
522	    if (stats.unknown > 0 || stats.anomaly > 0) {
523	      // 有未知或下降覆盖:不可判定,不触发也不恢复。
524	      lines.push(`  ${label}  undecidable (${coverage})  no alert action`);
525	      lines.push(...periodLines(day));
526	      continue;
527	    }
528	    const exceeded = stats.consumption > threshold;
529	    const cmp =
530	      `consumption=${formatKwh(stats.consumption)} kWh ` +
531	      `${exceeded ? '>' : '<='} threshold=${formatKwh(rule.thresholdMilli)} kWh`;
532	    const open = state.alerts.find(
533	      (a) => a.ruleId === rule.id && a.date === label && a.status === 'triggered',
534	    );
535	    if (exceeded) {
536	      if (open) {
537	        // 重复超限:保留原标识,不新增事件。
538	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered  ${coverage}`);
539	      } else {
540	        const id = `alert-${state.nextAlertNum++}`;
541	        if (alertIds.has(id)) {
542	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
543	          return 1;
544	        }
545	        alertIds.add(id);
546	        state.alerts.push({
547	          id,
548	          ruleId: rule.id,
549	          date: label,
550	          status: 'triggered',
551	          acknowledged: false,
552	          events: [
553	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
554	          ],
555	        });
556	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)  ${coverage}`);
557	      }
558	    } else {
559	      if (open) {
560	        open.status = 'recovered';
561	        open.events.push({
562	          seq: state.nextEventSeq++,
563	          type: 'recovered',
564	          consumptionMilli: stats.consumption.toString(),
565	        });
566	        lines.push(`  ${label}  ${cmp}  NORMAL  alert ${open.id} recovered  ${coverage}`);
567	      } else {
568	        lines.push(`  ${label}  ${cmp}  NORMAL  no alert  ${coverage}`);
569	      }
570	    }
571	    lines.push(...periodLines(day));
572	  }
573	
574	  try {
575	    saveAlertState(statePath, state);
576	  } catch (e) {
577	    if (e instanceof StoreError) {
578	      err(e.message);
579	      return 1;
580	    }
581	    throw e;
582	  }
583	
584	  console.log(
585	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  tz=${rule.tz}`,
586	  );
587	  for (const line of lines) console.log(line);
588	  return 0;
589	}
590	
591	/**
592	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
593	 * 给定日期范围时按规则时区的当地日期逐日展示当前计算的消耗或不可判定原因、
594	 * 实际 UTC 时段与各次告警;省略范围时展示有告警记录的全部日期。触发/恢复
595	 * 事件中的消耗为评估当时记录,不随后续数据变化改写。返回进程退出码。
596	 */
597	export function cmdAlerts(opts: { ruleId: string; from?: string; to?: string }): number {
598	  let state: AlertState;
599	  let rule: AlertRule;
600	  let env: RuleEnv;
601	  let fmt: Intl.DateTimeFormat;
602	  try {
603	    state = loadAlertState(alertFilePath());
604	    const found = state.rules.find((r) => r.id === opts.ruleId);
605	    if (!found) {
606	      err(`unknown rule '${opts.ruleId}'`);
607	      return 1;
608	    }
609	    rule = found;
610	    env = prepareEnv(rule);
611	    fmt = ruleFormat(rule);
612	  } catch (e) {
613	    if (e instanceof StoreError) {
614	      err(e.message);
615	      return 1;
616	    }
617	    throw e;
618	  }
619	
620	  // 待展示的当地日期(升序):给定范围时为范围内全部日期;省略范围时为有告警
621	  // 记录的全部日期。
622	  let labels: string[];
623	  if (opts.from !== undefined && opts.to !== undefined) {
624	    labels = localDateRange(fmt, opts.from, opts.to).map((e) => e.label);
625	  } else {
626	    labels = [
627	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
628	    ].sort();
629	  }
630	
631	  console.log(
632	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  tz=${rule.tz}`,
633	  );
634	  if (labels.length === 0) {
635	    console.log(`  no alerts recorded for rule '${rule.id}'`);
636	    return 0;
637	  }
638	
639	  // 各当地日期的实际 UTC 时段;整日被跳过的日期为 null。日历日期逐日递增,
640	  // 末日后延一天作为切分终点。
641	  const last = parseUtcDate(labels[labels.length - 1]) as number;
642	  const endLabel = formatIsoUtc(last + DAY_SECONDS).slice(0, 10);
643	  const byLabel = new Map<string, LocalDay | null>();
644	  for (const e of localDateRange(fmt, labels[0], endLabel)) byLabel.set(e.label, e.day);
645	
646	  const threshold = rule.thresholdMilli;
647	  for (const label of labels) {
648	    const day = byLabel.get(label) ?? null;
649	    if (day === null) {
650	      console.log(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})`);
651	    } else {
652	      const stats = computeRuleDay(env, day);
653	      if (stats.unknown > 0 || stats.anomaly > 0) {
654	        console.log(`  ${label}  undecidable (${coverageSuffix(stats)})`);
655	      } else {
656	        const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
657	        console.log(
658	          `  ${label}  consumption=${formatKwh(stats.consumption)} kWh ` +
659	            `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)  ${coverageSuffix(stats)}`,
660	        );
661	      }
662	      for (const line of periodLines(day)) console.log(line);
663	    }
664	    const alerts = state.alerts
665	      .filter((a) => a.ruleId === rule.id && a.date === label)
666	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
667	    if (alerts.length === 0) {
668	      console.log('    no alerts');
669	      continue;
670	    }
671	    for (const a of alerts) {
672	      console.log(
673	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
674	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
675	      );
676	      const events = a.events
677	        .map((e) => {
678	          const consumption =
679	            e.consumptionMilli !== undefined
680	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
681	              : '';
682	          return `#${e.seq} ${e.type}${consumption}`;
683	        })
684	        .join(', ');
685	      console.log(`      events: ${events}`);
686	    }
687	  }
688	  return 0;
689	}
690	
691	/**
692	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
693	 * 确认不改变超限或恢复状态。返回进程退出码。
694	 */
695	export function cmdAck(alertId: string): number {
696	  const statePath = alertFilePath();
697	  let state: AlertState;
698	  try {
699	    state = loadAlertState(statePath);
700	  } catch (e) {
701	    if (e instanceof StoreError) {
702	      err(e.message);
703	      return 1;
704	    }
705	    throw e;
706	  }
707	  const alert = state.alerts.find((a) => a.id === alertId);
708	  if (!alert) {
709	    err(`unknown alert '${alertId}'`);
710	    return 1;
711	  }
712	  if (alert.acknowledged) {
713	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
714	    return 0;
715	  }
716	  alert.acknowledged = true;
717	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
718	  try {
719	    saveAlertState(statePath, state);
720	  } catch (e) {
721	    if (e instanceof StoreError) {
722	      err(e.message);
723	      return 1;
724	    }
725	    throw e;
726	  }
727	  const rule = state.rules.find((r) => r.id === alert.ruleId);
728	  const target = rule ? ` ${targetLabel(rule)}` : '';
729	  console.log(
730	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
731	  );
732	  return 0;
733	}
734

