23	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
24	import { dirname } from 'node:path';
25	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
26	import { formatIsoUtc } from './time.ts';
27	import { localDays, loadTimezone } from './tz.ts';
28	import { formatKwh } from './value.ts';
29	
30	export interface GroupVersion {
31	  /** 生效时刻(含),epoch 秒。 */
32	  at: number;
33	  /** 成员设备标识,已去重并按字典序排序(规范形,成员顺序不影响等价性)。 */
34	  members: string[];
35	}
36	
37	export interface Group {
38	  /** 分组标识(非空、唯一,已去首尾空白,区分大小写)。 */
39	  id: string;
40	  /** 成员版本,按生效时刻升序。 */
41	  versions: GroupVersion[];
42	}
43	
44	function err(message: string): void {
45	  console.error(`meterwatch: ${message}`);
46	}
