1	// correct、undo 与 corrections 三个子命令的实现:可追溯的已存读数批量修正
2	// 及其整批撤销。
3	//
4	// 一次 correct 提交指定非空请求标识及至少一项修正;每项给出设备、实际时刻、
5	// 预期原读数和替换读数,只修改已有读数的累计值,不新增或删除读数。首次提交
6	// 逐项核验预期原值与操作前已存值精确一致,全部匹配才整体替换;任一不符整批
7	// 拒绝,不占用请求标识。读数替换与请求成功记录在同一存储文件中原子持久化,
8	// 写入失败保留操作前全部状态。同标识同内容重放直接返回原成功结果,不重新
9	// 校验、不再次替换;同标识异内容报冲突且保持状态。
10	//
11	// undo 提交指定非空撤销请求标识及目标修正请求标识,整批撤销一次已成功修正:
12	// 只恢复目标中实际改变过的读数,将其还原为该修正记录的原值,不新增或删除
13	// 读数,不允许挑选部分项。每个待恢复身份必须存在、当前值精确等于原替换值,
14	// 且没有后来尚未撤销、实际改变过该读数的修正;后来改回相同数值也不能绕过
15	// 来源检查,相关后续修正先撤销后才能再撤销较早请求。同值项不恢复、不阻塞;
16	// 全部为同值项的目标仍可成功撤销,恢复数为零。任一项不满足条件指出身份和
17	// 原因、整次拒绝,不占用撤销标识。撤销与修正请求共用唯一标识空间,成功标识
18	// 绑定操作类型和内容:同撤销标识、同目标重放返回原成功结果,不重新核验、
19	// 不重复恢复;同标识异内容或跨操作类型复用均报冲突。读数恢复、目标已撤销
20	// 标记(由撤销记录体现)与撤销成功记录同文件原子持久化,重启后状态一致。
21	
22	import {
23	  dataFilePath,
24	  loadData,
25	  saveData,
26	  StoreError,
27	  type CorrectionItem,
28	  type Reading,
29	  type StoreData,
30	} from './store.ts';
31	import { loadCheckedSeriesByDevice } from './groups.ts';
32	import { formatIsoUtc } from './time.ts';
33	import { formatKwh } from './value.ts';
34	
35	function err(message: string): void {
36	  console.error(`meterwatch: ${message}`);
37	}
38	
39	function sameItem(a: CorrectionItem, b: CorrectionItem): boolean {
40	  return (
41	    a.device === b.device &&
42	    a.ts === b.ts &&
43	    a.expectedMilli === b.expectedMilli &&
44	    a.replacementMilli === b.replacementMilli
45	  );
46	}
47	
48	/** 内容等价:修正项集合相同,顺序无关(时刻已按 epoch 秒、数值已按毫千瓦时规范化)。 */
49	function itemsEquivalent(a: CorrectionItem[], b: CorrectionItem[]): boolean {
50	  if (a.length !== b.length) return false;
51	  const used = new Array<boolean>(b.length).fill(false);
52	  for (const item of a) {
53	    let found = false;
54	    for (let j = 0; j < b.length; j++) {
55	      if (!used[j] && sameItem(item, b[j])) {
56	        used[j] = true;
57	        found = true;
58	        break;
59	      }
60	    }
61	    if (!found) return false;
62	  }
63	  return true;
64	}
65	
66	/** 实际改变的读数条数:提交时预期原值已与已存值一致,故替换值不同于预期原值即为改变。 */
67	function changedCount(items: CorrectionItem[]): number {
68	  return items.filter((it) => it.expectedMilli !== it.replacementMilli).length;
69	}
70	
71	function reportSuccess(requestId: string, items: CorrectionItem[]): void {
72	  console.log(
73	    `correction '${requestId}' committed: ${items.length} item(s), ${changedCount(items)} reading(s) changed`,
74	  );
75	}
76	
77	function reportUndoSuccess(requestId: string, targetId: string, restored: number): void {
78	  console.log(`undo '${requestId}' committed: target='${targetId}', ${restored} reading(s) restored`);
79	}
80	
81	/** 读取存储;损坏或不可读时报错并返回 null。 */
82	function loadChecked(storePath: string): StoreData | null {
83	  try {
84	    return loadData(storePath);
85	  } catch (e) {
86	    if (e instanceof StoreError) {
87	      err(e.message);
88	      return null;
89	    }
90	    throw e;
91	  }
92	}
93	
94	/**
95	 * 载入数据并检查全库重复读数身份;任一步失败报错并返回 null。
96	 * 修正、撤销及历史查询(含重放)都不得绕过该检查。
97	 */
98	function loadVerified(storePath: string): { data: StoreData; byDevice: Map<string, Reading[]> } | null {
99	  const data = loadChecked(storePath);
100	  if (data === null) return null;
101	  try {
102	    return { data, byDevice: loadCheckedSeriesByDevice(data.readings) };
103	  } catch (e) {
104	    if (e instanceof StoreError) {
105	      err(e.message);
106	      return null;
107	    }
108	    throw e;
109	  }
110	}
111	
112	/** 已被撤销的修正请求标识集合(由撤销记录推导,修正记录本身保持原内容不变)。 */
113	function undoneTargetIds(data: StoreData): Set<string> {
114	  return new Set(data.undos.map((u) => u.targetId));
115	}
116	
117	/**
118	 * 提交一批修正。requestId 与 items 均由调用方完成格式解析(去空白、
119	 * 时间与数值已规范化)。返回进程退出码。
120	 */
121	export function cmdCorrect(requestId: string, items: CorrectionItem[]): number {
122	  // 同批同一读数身份(设备 + 实际时刻)只允许一项。
123	  const seen = new Set<string>();
124	  for (const it of items) {
125	    const k = `${it.device} ${it.ts}`;
126	    if (seen.has(k)) {
127	      err(`duplicate correction item for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
128	      return 2;
129	    }
130	    seen.add(k);
131	  }
132	
133	  const storePath = dataFilePath();
134	  const loaded = loadVerified(storePath);
135	  if (loaded === null) return 1;
136	  const { data, byDevice } = loaded;
137	
138	  // 重放:同标识同内容直接返回原成功结果,不重新校验当前读数、不再次替换
139	  // (即使这些读数后来又被其他请求修正,或本修正后来被撤销);同标识异内容
140	  // 报冲突且保持状态。
141	  const prior = data.corrections.find((c) => c.requestId === requestId);
142	  if (prior !== undefined) {
143	    if (itemsEquivalent(prior.items, items)) {
144	      reportSuccess(requestId, prior.items);
145	      return 0;
146	    }
147	    err(`correction request '${requestId}' conflicts with an already committed request of the same id; nothing was changed`);
148	    return 1;
149	  }
150	  // 撤销与修正共用唯一标识空间:跨操作类型复用标识报冲突。
151	  if (data.undos.some((u) => u.requestId === requestId)) {
152	    err(`correction request '${requestId}' conflicts with an already committed undo request of the same id; nothing was changed`);
153	    return 1;
154	  }
155	
156	  // 核验:每项身份必须存在,且预期原值与操作前已存值精确一致。
157	  const errors: string[] = [];
158	  const readings: Array<{ reading: Reading; item: CorrectionItem }> = [];
159	  for (const it of items) {
160	    const series = byDevice.get(it.device);
161	    const reading = series?.find((r) => r.ts === it.ts);
162	    if (reading === undefined) {
163	      errors.push(`no stored reading for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
164	      continue;
165	    }
166	    if (reading.milli !== it.expectedMilli) {
167	      errors.push(
168	        `stored value mismatch for device '${it.device}' at ${formatIsoUtc(it.ts)}: ` +
169	          `expected ${formatKwh(it.expectedMilli)} kWh but stored ${formatKwh(reading.milli)} kWh`,
170	      );
171	      continue;
172	    }
173	    readings.push({ reading, item: it });
174	  }
175	  if (errors.length > 0) {
176	    for (const e of errors) err(e);
177	    err(`correction '${requestId}' rejected: ${errors.length} item(s) failed; nothing was changed`);
178	    return 1;
179	  }
180	
181	  // 整体替换,并把请求成功记录与读数替换同文件原子持久化。
182	  for (const { reading, item } of readings) reading.milli = item.replacementMilli;
183	  try {
184	    saveData(storePath, {
185	      readings: data.readings,
186	      corrections: data.corrections.concat([{ requestId, items }]),
187	      undos: data.undos,
188	    });
189	  } catch (e) {
190	    if (e instanceof StoreError) {
191	      err(e.message);
192	      return 1;
193	    }
194	    throw e;
195	  }
196	  reportSuccess(requestId, items);
197	  return 0;
198	}
199	
200	/**
201	 * 整批撤销一次已成功修正。requestId 与 targetId 均由调用方完成格式解析
202	 * (非空、已去首尾空白)。返回进程退出码。
203	 */
204	export function cmdUndo(requestId: string, targetId: string): number {
205	  const storePath = dataFilePath();
206	  const loaded = loadVerified(storePath);
207	  if (loaded === null) return 1;
208	  const { data, byDevice } = loaded;
209	
210	  // 重放:同撤销标识、同目标直接返回原成功结果,不重新核验撤销资格、不重复
211	  // 恢复;同标识异目标报冲突。修正标识被撤销复用属跨操作类型冲突。
212	  const priorUndo = data.undos.find((u) => u.requestId === requestId);
213	  if (priorUndo !== undefined) {
214	    if (priorUndo.targetId === targetId) {
215	      reportUndoSuccess(priorUndo.requestId, priorUndo.targetId, priorUndo.restored);
216	      return 0;
217	    }
218	    err(`undo request '${requestId}' conflicts with an already committed undo request of the same id; nothing was changed`);
219	    return 1;
220	  }
221	  if (data.corrections.some((c) => c.requestId === requestId)) {
222	    err(`undo request '${requestId}' conflicts with an already committed correction request of the same id; nothing was changed`);
223	    return 1;
224	  }
225	
226	  // 目标只能是成功修正,不能是撤销请求;未知或已撤销目标报错。
227	  const targetIndex = data.corrections.findIndex((c) => c.requestId === targetId);
228	  if (targetIndex === -1) {
229	    if (data.undos.some((u) => u.requestId === targetId)) {
230	      err(`undo target '${targetId}' is an undo request, not a committed correction; nothing was changed`);
231	    } else {
232	      err(`unknown correction '${targetId}': no committed correction with that request id; nothing was changed`);
233	    }
234	    return 1;
235	  }
236	  const undone = undoneTargetIds(data);
237	  if (undone.has(targetId)) {
238	    const by = data.undos.find((u) => u.targetId === targetId);
239	    err(`correction '${targetId}' is already undone by undo '${by?.requestId}'; nothing was changed`);
240	    return 1;
241	  }
242	  const target = data.corrections[targetIndex];
243	
244	  // 后来尚未撤销、实际改变过某读数身份的修正会阻塞对该身份的恢复;
245	  // 同值项(预期原值等于替换值)不恢复也不阻塞。
246	  const blockerByKey = new Map<string, string>();
247	  for (let i = targetIndex + 1; i < data.corrections.length; i++) {
248	    const later = data.corrections[i];
249	    if (undone.has(later.requestId)) continue;
250	    for (const it of later.items) {
251	      if (it.expectedMilli !== it.replacementMilli) {
252	        blockerByKey.set(`${it.device} ${it.ts}`, later.requestId);
253	      }
254	    }
255	  }
256	
257	  // 核验:每个待恢复身份必须存在、当前值精确等于原替换值、且无阻塞来源。
258	  const errors: string[] = [];
259	  const restores: Array<{ reading: Reading; item: CorrectionItem }> = [];
260	  for (const it of target.items) {
261	    if (it.expectedMilli === it.replacementMilli) continue;
262	    const key = `${it.device} ${it.ts}`;
263	    const series = byDevice.get(it.device);
264	    const reading = series?.find((r) => r.ts === it.ts);
265	    if (reading === undefined) {
266	      errors.push(`no stored reading for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
267	      continue;
268	    }
269	    if (reading.milli !== it.replacementMilli) {
270	      errors.push(
271	        `current value mismatch for device '${it.device}' at ${formatIsoUtc(it.ts)}: ` +
272	          `expected ${formatKwh(it.replacementMilli)} kWh (replacement of '${targetId}') but stored ${formatKwh(reading.milli)} kWh`,
273	      );
274	      continue;
275	    }
276	    const blocker = blockerByKey.get(key);
277	    if (blocker !== undefined) {
278	      errors.push(
279	        `reading for device '${it.device}' at ${formatIsoUtc(it.ts)} was also changed by later correction '${blocker}' (not yet undone); undo '${blocker}' first`,
280	      );
281	      continue;
282	    }
283	    restores.push({ reading, item: it });
284	  }
285	  if (errors.length > 0) {
286	    for (const e of errors) err(e);
287	    err(`undo '${requestId}' of correction '${targetId}' rejected: ${errors.length} item(s) failed; nothing was changed`);
288	    return 1;
289	  }
290	
291	  // 恢复为目标记录的原值;读数恢复与撤销成功记录同文件原子持久化,
292	  // 目标修正内容保留,已撤销标记由撤销记录体现。
293	  for (const { reading, item } of restores) reading.milli = item.expectedMilli;
294	  try {
295	    saveData(storePath, {
296	      readings: data.readings,
297	      corrections: data.corrections,
298	      undos: data.undos.concat([{ requestId, targetId, restored: restores.length }]),
299	    });
300	  } catch (e) {
301	    if (e instanceof StoreError) {
302	      err(e.message);
303	      return 1;
304	    }
305	    throw e;
306	  }
307	  reportUndoSuccess(requestId, targetId, restores.length);
308	  return 0;
309	}
310	
311	/**
312	 * 按成功提交顺序显示修正历史(请求标识、各项设备、时刻、原值和替换值及
313	 * 已撤销标记),另按成功发生顺序显示撤销请求与目标关系。只读,不写入数据。
314	 * 返回进程退出码。
315	 */
316	export function cmdCorrections(): number {
317	  const storePath = dataFilePath();
318	  const loaded = loadVerified(storePath);
319	  if (loaded === null) return 1;
320	  const { data } = loaded;
321	  if (data.corrections.length === 0 && data.undos.length === 0) {
322	    console.log('no corrections recorded');
323	    return 0;
324	  }
325	  const undoneBy = new Map(data.undos.map((u) => [u.targetId, u.requestId]));
326	  for (const c of data.corrections) {
327	    const undoId = undoneBy.get(c.requestId);
328	    const marker = undoId === undefined ? '' : `  (undone by '${undoId}')`;
329	    console.log(
330	      `correction '${c.requestId}': ${c.items.length} item(s), ${changedCount(c.items)} reading(s) changed${marker}`,
331	    );
332	    for (const it of c.items) {
333	      console.log(
334	        `  ${formatIsoUtc(it.ts)}  device=${it.device}  expected=${formatKwh(it.expectedMilli)} kWh  replacement=${formatKwh(it.replacementMilli)} kWh`,
335	      );
336	    }
337	  }
338	  for (const u of data.undos) {
339	    console.log(`undo '${u.requestId}': target='${u.targetId}', ${u.restored} reading(s) restored`);
340	  }
341	  return 0;
342	}
