function commitRestore(bodies: Record<StoreFile, string>): string | null {
  const dir = dataDirPath();
  mkdirSync(dir, { recursive: true });
  const target = (f: string) => join(dir, f);
  const tmp = (f: string) => join(dir, f + NEW_SUFFIX);
  const old = (f: string) => join(dir, f + OLD_SUFFIX);
  const journal = join(dir, JOURNAL_FILE);

  // 1. 新内容写入临时文件并落盘。
  try {
    for (const f of STORE_FILES) {
      writeFileSync(tmp(f), bodies[f], 'utf8');
      fsyncFile(tmp(f));
    }
  } catch (e) {
    for (const f of STORE_FILES) { try { unlinkSync(tmp(f)); } catch {} }
    return `cannot write restore temp files in ${dir}: ${(e as Error).message}; previous state preserved`;
  }
  // 2. 现有存储改名为备份(保留旧状态用于失败回退)。
  const backedUp: string[] = [];
  try {
    for (const f of STORE_FILES) {
      if (existsSync(target(f))) { renameSync(target(f), old(f)); backedUp.push(f); }
    }
  } catch (e) {
    for (const f of backedUp) { try { renameSync(old(f), target(f)); } catch {} }
    for (const f of STORE_FILES) { try { unlinkSync(tmp(f)); } catch {} }
    return `cannot prepare restore in ${dir}: ${(e as Error).message}; previous state preserved`;
  }
  // 3. 提交日志:此后的中断由下次启动的恢复流程收敛到完整状态。
  try {
    writeFileSync(journal, JSON.stringify({ phase: 'committing' }) + '\n', 'utf8');
    fsyncFile(journal);
  } catch (e) {
    for (const f of backedUp) { try { renameSync(old(f), target(f)); } catch {} }
    for (const f of STORE_FILES) { try { unlinkSync(tmp(f)); } catch {} }
    return `cannot write restore journal in ${dir}: ${(e as Error).message}; previous state preserved`;
  }
  // 4. 逐个换入新存储。
  try {
    for (const f of STORE_FILES) renameSync(tmp(f), target(f));
  } catch (e) {
    // 回退到恢复前状态;回退本身失败时保留日志,下次启动恢复。
    let rollbackErr: string | null = null;
    try {
      writeFileSync(journal, JSON.stringify({ phase: 'rolling-back' }) + '\n', 'utf8');
      rollBack(dir);
      unlinkSync(journal);
    } catch (re) {
      rollbackErr = (re as Error).message;
    }
    if (rollbackErr === null) {
      return `restore failed during commit: ${(e as Error).message}; previous state preserved`;
    }
    return `restore failed during commit: ${(e as Error).message}; could not restore previous state (${rollbackErr}); recovery will run on next start`;
  }
  // 5. 清理备份与日志,提交完成。
  for (const f of STORE_FILES) { try { unlinkSync(old(f)); } catch {} }
  try { unlinkSync(journal); } catch {}
  return null;
}
